<?php require 'db.php'; header('Content-Type: application/json; charset=utf-8'); try{$a=$_POST['accion']??$_GET['accion']??'listar'; if($a==='listar'){$s=$pdo->query('SELECT * FROM Socios ORDER BY nombre,apellidos');echo json_encode(['ok'=>true,'datos'=>$s->fetchAll()],JSON_UNESCAPED_UNICODE);exit;} if($a==='crear'){$s=$pdo->prepare('INSERT INTO Socios(documento,nombre,apellidos,direccion,telefono) VALUES(?,?,?,?,?)');$s->execute([trim($_POST['documento']),trim($_POST['nombre']),trim($_POST['apellidos']),trim($_POST['direccion']??''),trim($_POST['telefono']??'')]);echo json_encode(['ok'=>true,'mensaje'=>'Socio creado correctamente.'],JSON_UNESCAPED_UNICODE);exit;} if($a==='actualizar'){$s=$pdo->prepare('UPDATE Socios SET nombre=?,apellidos=?,direccion=?,telefono=? WHERE documento=?');$s->execute([trim($_POST['nombre']),trim($_POST['apellidos']),trim($_POST['direccion']??''),trim($_POST['telefono']??''),trim($_POST['documento'])]);echo json_encode(['ok'=>true,'mensaje'=>'Socio actualizado correctamente.'],JSON_UNESCAPED_UNICODE);exit;} if($a==='eliminar'){$s=$pdo->prepare('DELETE FROM Socios WHERE documento=?');$s->execute([trim($_POST['documento'])]);echo json_encode(['ok'=>true,'mensaje'=>'Socio eliminado correctamente.'],JSON_UNESCAPED_UNICODE);exit;} http_response_code(400);echo json_encode(['ok'=>false,'mensaje'=>'Acción no válida.'],JSON_UNESCAPED_UNICODE);}catch(PDOException $e){http_response_code(400);echo json_encode(['ok'=>false,'mensaje'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
